mapper.select:
select b_id bId, repair_id repairId, `date`, content, price, declarant, car_id carId, operate, community_id communityId
from business_pubcar_car_repair
where b_id = #{bId} and operate= #{operate}

select t.date,t.create_time,t.create_time createTime,t.price,t.repair_id,t.repair_id
repairId,t.status_cd,t.status_cd statusCd,t.b_id,t.b_id bId,t.community_id,t.community_id
communityId,t.content,t.declarant,t.car_id,t.car_id carId
from pubcar_car_repair t


        t.status_cd= #{statusCd}


        and t.date= #{date}


        and t.create_time= #{createTime}


        and t.price= #{price}


        and t.repair_id= #{repairId}


        and t.b_id= #{bId}


        and t.community_id= #{communityId}


        and t.content like concat('%',#{content},'%')


        and t.declarant like concat('%',#{declarant},'%')


        and t.car_id= #{carId}


order by t.create_time desc

    limit #{page}, #{row}

